import random
import struct
import datetime

# Generator for valid Apple Property List (plist) byte streams.
# We focus on producing syntactically valid XML plists with various root types
# and some minimal binary plists. Keep size <= 4096 bytes.

XML_HEADER = '<?xml version="1.0" encoding="UTF-8"?>\n'
DOCTYPE = '<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">\n'
PLIST_OPEN = '<plist version="1.0">\n'
PLIST_CLOSE = '</plist>\n'

XML_ESCAPES = {
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&apos;',
}


def _xml_escape(s: str) -> str:
    return ''.join(XML_ESCAPES.get(ch, ch) for ch in s)


def _rand_bool(rng: random.Random) -> bool:
    return bool(rng.getrandbits(1))


def _rand_int(rng: random.Random) -> int:
    # Mix of small and large values
    choice = rng.randrange(6)
    if choice == 0:
        return 0
    if choice == 1:
        return -1
    if choice == 2:
        return 1
    if choice == 3:
        # 32-bit range
        return rng.randint(-2**31, 2**31 - 1)
    if choice == 4:
        # 64-bit range
        return rng.randint(-2**63, 2**63 - 1)
    # powers of two and boundaries
    return rng.choice([2**8, 2**16, 2**31 - 1, 2**63 - 1])


def _rand_float(rng: random.Random) -> float:
    # Diverse float values
    special = [0.0, -0.0, 1.0, -1.0, 3.141592653589793, 2.718281828459045,
               1e-300, 1e300]
    if rng.random() < 0.5:
        return rng.choice(special)
    # uniform in a wide-ish range
    sign = -1.0 if _rand_bool(rng) else 1.0
    return sign * 10 ** rng.uniform(-10, 10)


def _rand_bytes(rng: random.Random, maxlen: int = 64) -> bytes:
    n = rng.randint(0, maxlen)
    return bytes(rng.getrandbits(8) for _ in range(n))


def _rand_uuid(rng: random.Random) -> str:
    # Version 4-like UUID
    ints = [rng.getrandbits(8) for _ in range(16)]
    ints[6] = (ints[6] & 0x0F) | 0x40  # version
    ints[8] = (ints[8] & 0x3F) | 0x80  # variant
    hexs = ''.join(f'{b:02x}' for b in ints)
    return f'{hexs[0:8]}-{hexs[8:12]}-{hexs[12:16]}-{hexs[16:20]}-{hexs[20:32]}'


def _rand_date_iso8601(rng: random.Random) -> str:
    # RFC 3339-like, commonly used in plist <date> as UTC 'YYYY-MM-DDTHH:MM:SSZ'
    # Pick a reasonable range
    year = rng.randint(1970, 2050)
    month = rng.randint(1, 12)
    # naive days per month
    days_in_month = [31, 29 if (year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    day = rng.randint(1, days_in_month[month - 1])
    hour = rng.randint(0, 23)
    minute = rng.randint(0, 59)
    second = rng.randint(0, 59)
    return f"{year:04d}-{month:02d}-{day:02d}T{hour:02d}:{minute:02d}:{second:02d}Z"


def _xml_data_from_bytes(b: bytes) -> str:
    # Represent binary data as base64 per plist DTD
    import base64
    if not b:
        return ''
    return base64.b64encode(b).decode('ascii')


def _rand_string(rng: random.Random, maxlen: int = 64) -> str:
    # Produce a mix of ASCII, XML entities, and some UTF-8 codepoints
    length = rng.randint(0, maxlen)
    chars = []
    for _ in range(length):
        t = rng.randrange(5)
        if t == 0:
            chars.append(chr(rng.randint(0x20, 0x7E)))  # printable ASCII
        elif t == 1:
            chars.append(rng.choice(['&', '<', '>', '"', "'"]))
        elif t == 2:
            chars.append('\n')
        elif t == 3:
            # BMP non-ASCII
            chars.append(chr(rng.randint(0x00A0, 0x07FF)))
        else:
            # Some higher plane
            chars.append(chr(rng.randint(0x0800, 0xD7FF)))
    return ''.join(chars)


def _xml_value(rng: random.Random, depth: int) -> str:
    # Generate a plist XML value element recursively
    # depth controls nesting to stay within size limits
    kinds = ['string', 'integer', 'real', 'data', 'date', 'true', 'false', 'array', 'dict']
    # Bias toward containers when depth allows
    if depth <= 0:
        kinds = ['string', 'integer', 'real', 'data', 'date', 'true', 'false']
    kind = rng.choice(kinds)

    if kind == 'string':
        s = _xml_escape(_rand_string(rng))
        return f'<string>{s}</string>'
    if kind == 'integer':
        return f'<integer>{_rand_int(rng)}</integer>'
    if kind == 'real':
        # plist allows <real> with decimal or exponent
        val = _rand_float(rng)
        return f'<real>{val}</real>'
    if kind == 'data':
        b64 = _xml_data_from_bytes(_rand_bytes(rng, 96))
        return f'<data>{b64}</data>'
    if kind == 'date':
        return f'<date>{_rand_date_iso8601(rng)}</date>'
    if kind in ('true', 'false'):
        return f'<{kind}/>'
    if kind == 'array':
        n = rng.randint(0, 6)
        items = [_xml_value(rng, depth - 1) for _ in range(n)]
        return '<array>' + ''.join(items) + '</array>'
    # dict
    n = rng.randint(0, 6)
    parts = []
    for _ in range(n):
        key = _xml_escape(_rand_string(rng, 24))
        # Sprinkle a few known keys to encourage specific library paths
        if rng.random() < 0.2:
            key = rng.choice(['CFBundleIdentifier', 'CFBundleVersion', 'UID', 'UUID', 'NS.objects', 'NS.keys'])
        parts.append(f'<key>{key}</key>')
        # sometimes ensure a UUID or string for known keys
        if key in ('UUID', 'UID') and rng.random() < 0.7:
            parts.append(f'<string>{_xml_escape(_rand_uuid(rng))}</string>')
        else:
            parts.append(_xml_value(rng, depth - 1))
    return '<dict>' + ''.join(parts) + '</dict>'


def _make_xml_plist(rng: random.Random) -> bytes:
    body = _xml_value(rng, depth=rng.randint(1, 4))
    xml = XML_HEADER + DOCTYPE + PLIST_OPEN + body + PLIST_CLOSE
    # Ensure UTF-8 bytes
    data = xml.encode('utf-8')
    if len(data) > 4096:
        # Trim by reducing container sizes: regenerate with smaller depth
        body = _xml_value(rng, depth=1)
        xml = XML_HEADER + DOCTYPE + PLIST_OPEN + body + PLIST_CLOSE
        data = xml.encode('utf-8')
    return data[:4096]


# Minimal binary plist builder (bplist00) for small dictionaries/arrays of simple types.
# This is a simplified generator to produce valid but small binary plists.
# Format reference: Apple Binary Property List v0.00

class BPBuilder:
    def __init__(self):
        self.objs = []  # list of (type, payload)

    def add(self, obj):
        # returns object index
        self.objs.append(obj)
        return len(self.objs) - 1

    def _int_obj(self, n: int):
        # integer object: 0x10 | k, followed by 1,2,4,8 bytes big-endian
        # choose minimal size that fits signed magnitude
        # We'll store as unsigned magnitude big-endian per spec
        if -128 <= n <= 127:
            marker = bytes([0x10 | 0])
            return marker + (n & 0xFF).to_bytes(1, 'big', signed=False)
        if -32768 <= n <= 32767:
            marker = bytes([0x10 | 1])
            return marker + (n & 0xFFFF).to_bytes(2, 'big', signed=False)
        if -2147483648 <= n <= 2147483647:
            marker = bytes([0x10 | 2])
            return marker + (n & 0xFFFFFFFF).to_bytes(4, 'big', signed=False)
        marker = bytes([0x10 | 3])
        return marker + (n & 0xFFFFFFFFFFFFFFFF).to_bytes(8, 'big', signed=False)

    def _bool_obj(self, v: bool):
        return bytes([0x09 if v else 0x08])

    def _data_obj(self, b: bytes):
        # 0x40 | len or 0x4F + length obj
        L = len(b)
        if L < 0x0F:
            return bytes([0x40 | L]) + b
        else:
            llen = self._len_obj(L)
            return bytes([0x4F]) + llen + b

    def _ascii_obj(self, s: str):
        b = s.encode('ascii', 'ignore')
        L = len(b)
        if L < 0x0F:
            return bytes([0x50 | L]) + b
        else:
            return bytes([0x5F]) + self._len_obj(L) + b

    def _utf16_obj(self, s: str):
        # store as UTF-16BE without BOM, length is number of characters
        b = s.encode('utf-16-be')
        L = len(s)
        if L < 0x0F:
            return bytes([0x60 | L]) + b
        else:
            return bytes([0x6F]) + self._len_obj(L) + b

    def _len_obj(self, L: int) -> bytes:
        # length object for variable-sized markers: integer object specifying length
        # pick minimal int size
        if L < 0x100:
            return bytes([0x10 | 0]) + L.to_bytes(1, 'big')
        if L < 0x10000:
            return bytes([0x10 | 1]) + L.to_bytes(2, 'big')
        if L < 0x100000000:
            return bytes([0x10 | 2]) + L.to_bytes(4, 'big')
        return bytes([0x10 | 3]) + L.to_bytes(8, 'big')

    def _array_obj(self, idxs):
        L = len(idxs)
        ref_size = self._ref_size(len(self.objs))
        refs = b''.join(i.to_bytes(ref_size, 'big') for i in idxs)
        if L < 0x0F:
            return bytes([0xA0 | L]) + refs
        else:
            return bytes([0xAF]) + self._len_obj(L) + refs

    def _dict_obj(self, keys, vals):
        L = len(keys)
        ref_size = self._ref_size(len(self.objs))
        krefs = b''.join(k.to_bytes(ref_size, 'big') for k in keys)
        vrefs = b''.join(v.to_bytes(ref_size, 'big') for v in vals)
        if L < 0x0F:
            return bytes([0xD0 | L]) + krefs + vrefs
        else:
            return bytes([0xDF]) + self._len_obj(L) + krefs + vrefs

    def _ref_size(self, n_objs):
        # number of bytes to encode an object reference index
        if n_objs <= 0xFF:
            return 1
        if n_objs <= 0xFFFF:
            return 2
        if n_objs <= 0xFFFFFFFF:
            return 4
        return 8

    def build_sample(self, rng: random.Random) -> bytes:
        # Build a small dictionary with mixture of values
        # Create some strings for keys
        key_idxs = []
        val_idxs = []
        # Collect objects as raw encoded blobs after planning
        encoded = []

        # Temporary table to map obj index to encoded blob after creation
        def add_encoded(blob: bytes):
            self.objs.append(None)
            encoded.append(blob)
            return len(self.objs) - 1

        # a few keys
        keys = [
            'CFBundleIdentifier', 'CFBundleVersion', 'UUID', 'Name', 'Count'
        ]
        rng.shuffle(keys)
        n_pairs = rng.randint(2, min(5, len(keys)))
        pairs = []
        for i in range(n_pairs):
            k = keys[i]
            # store keys as ASCII when possible
            k_idx = add_encoded(self._ascii_obj(k))
            key_idxs.append(k_idx)
            # choose value type
            vt = rng.choice(['str', 'int', 'bool', 'data', 'array'])
            if vt == 'str':
                s = _rand_uuid(rng) if k == 'UUID' else _rand_string(rng, 16)
                # prefer UTF-16 for variety sometimes
                if rng.random() < 0.3:
                    v_idx = add_encoded(self._utf16_obj(s))
                else:
                    v_idx = add_encoded(self._ascii_obj(s))
            elif vt == 'int':
                v_idx = add_encoded(self._int_obj(rng.randint(0, 100000)))
            elif vt == 'bool':
                v_idx = add_encoded(self._bool_obj(_rand_bool(rng)))
            elif vt == 'data':
                v_idx = add_encoded(self._data_obj(_rand_bytes(rng, 32)))
            else:
                # small array of integers
                arr_items = []
                m = rng.randint(0, 4)
                for _ in range(m):
                    arr_items.append(add_encoded(self._int_obj(rng.randint(0, 1000))))
                v_idx = add_encoded(self._array_obj(arr_items))
            val_idxs.append(v_idx)
            pairs.append((k_idx, v_idx))

        dict_idx = add_encoded(self._dict_obj(key_idxs, val_idxs))

        # Now assemble full file: header, object table, offset table, trailer
        # object table is concatenation of encoded blobs in order
        obj_table = b''.join(encoded)
        n_objs = len(encoded)
        ref_size = self._ref_size(n_objs)
        # Offsets are from beginning of object table
        offsets = []
        cur = 0
        for blob in encoded:
            offsets.append(cur)
            cur += len(blob)
        offset_table = b''.join(off.to_bytes(4, 'big') for off in offsets)
        offset_size = 4  # we used 4-byte offsets
        top_object = dict_idx  # last added is the dict
        offset_table_start = 8 + len(obj_table)  # header 8 bytes, then objects

        header = b'bplist00'
        trailer = bytearray(32)
        # trailer layout:
        # 6 unused, 1 offset_size, 1 ref_size, 8 num_objs, 8 top_object, 8 offset_table_start
        trailer[6] = offset_size
        trailer[7] = ref_size
        trailer[8:16] = (n_objs).to_bytes(8, 'big')
        trailer[16:24] = (top_object).to_bytes(8, 'big')
        trailer[24:32] = (offset_table_start).to_bytes(8, 'big')

        data = header + obj_table + offset_table + bytes(trailer)
        return data


def _make_binary_plist(rng: random.Random) -> bytes:
    b = BPBuilder().build_sample(rng)
    # Ensure size limit
    return b[:4096]


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Choose format with some bias to XML (often more widely supported)
    if rng.random() < 0.7:
        data = _make_xml_plist(rng)
    else:
        data = _make_binary_plist(rng)

    # Occasionally force specific shapes likely to exercise getters:
    # - Root dict with a UUID string value
    # - Root array with elements
    if len(data) < 1024 and rng.random() < 0.4:
        # Create a targeted XML plist
        if rng.random() < 0.5:
            body = (
                '<dict>'
                '<key>Name</key><string>' + _xml_escape(_rand_string(rng, 20)) + '</string>'
                '<key>UUID</key><string>' + _xml_escape(_rand_uuid(rng)) + '</string>'
                '<key>Count</key><integer>' + str(rng.randint(0, 100)) + '</integer>'
                '<key>Data</key><data>' + _xml_data_from_bytes(_rand_bytes(rng, 48)) + '</data>'
                '</dict>'
            )
        else:
            elems = ''.join(_xml_value(rng, 2) for _ in range(rng.randint(1, 6)))
            body = '<array>' + elems + '</array>'
        xml = (XML_HEADER + DOCTYPE + PLIST_OPEN + body + PLIST_CLOSE).encode('utf-8')
        if len(xml) <= 4096:
            data = xml
    return data
